`ifndef XIL_XECLIB
  reg attr_test;
  reg attr_err;
  
  initial begin
  trig_attr = 1'b0;
  `ifdef XIL_ATTR_TEST
    attr_test = 1'b1;
  `else
    attr_test = 1'b0;
  `endif
    attr_err = 1'b0;
    #1;
    trig_attr = ~trig_attr;
  end
`endif

`ifndef XIL_XECLIB
  always @ (trig_attr) begin
    #1;
    if ((attr_test == 1'b1) ||
        ((BOT_CHIPPIPE_MODE_REG != "GT_DIR") &&
         (BOT_CHIPPIPE_MODE_REG != "CPM") &&
         (BOT_CHIPPIPE_MODE_REG != "HSDP"))) begin
      $display("Error: [Unisim %s-101] BOT_CHIPPIPE_MODE attribute is set to %s.  Legal values for this attribute are GT_DIR, CPM or HSDP. Instance: %m", MODULE_NAME, BOT_CHIPPIPE_MODE_REG);
      attr_err = 1'b1;
    end
    
    if ((attr_test == 1'b1) ||
        ((BOT_PL_MUX_MODE_REG != "GT_DIR") &&
         (BOT_PL_MUX_MODE_REG != "AXI") &&
         (BOT_PL_MUX_MODE_REG != "CXL") &&
         (BOT_PL_MUX_MODE_REG != "CXL_AXI") &&
         (BOT_PL_MUX_MODE_REG != "STRM"))) begin
